// GPT-owned Echo multiring v10: bounded deterministic synthetic study. No canonical imports.
const SEEDS=[5501,5502,5503,5504];
function rng(seed){let x=seed>>>0;return ()=>{x=(1664525*x+1013904223)>>>0;return x/4294967296;};}
function features(i,mode){let a=Math.sin((i+1)*0.31),b=Math.cos((i+1)*0.17);return mode==='swap'?[b,a]:[a,b];}
function fit(rows,quadratic){let n=quadratic?3:2, A=Array.from({length:n},()=>Array(n).fill(0)),v=Array(n).fill(0);for(let r of rows){let x=quadratic?[r.a,r.b,r.a*r.b]:[r.a,r.b];for(let j=0;j<n;j++){v[j]+=x[j]*r.y;for(let k=0;k<n;k++)A[j][k]+=x[j]*x[k];}}for(let j=0;j<n;j++)A[j][j]+=1e-4;for(let j=0;j<n;j++){let p=j;for(let k=j+1;k<n;k++)if(Math.abs(A[k][j])>Math.abs(A[p][j]))p=k;[A[j],A[p]]=[A[p],A[j]];[v[j],v[p]]=[v[p],v[j]];let q=A[j][j];for(let k=j;k<n;k++)A[j][k]/=q;v[j]/=q;for(let h=0;h<n;h++)if(h!==j){let z=A[h][j];for(let k=j;k<n;k++)A[h][k]-=z*A[j][k];v[h]-=z*v[j];}}return v;}
function predict(r,w){return w[0]*r.a+w[1]*r.b+(w.length===3?w[2]*r.a*r.b:0);}
function mse(rows,w){return rows.reduce((s,r)=>s+(r.y-predict(r,w))**2,0)/rows.length;}
function world(seed,kind,shift=false){let rand=rng(seed),rows=[];for(let i=0;i<216;i++){let [a,b]=features(i);a+=0.18*(rand()-.5);b+=0.18*(rand()-.5);let noise=.1*(rand()-.5),y=kind==='signal'?(0.25*a+0.65*b+(shift?-.7:.8)*a*b+noise):kind==='nullA'?noise:((i%2?1:-1)*.4+noise);rows.push({a,b,y});}return rows;}
function run(seed){let train=world(seed,'signal').slice(0,108),hold=world(seed+77,'signal').slice(108),shift=world(seed+77,'signal',true).slice(108),nullA=world(seed+77,'nullA').slice(108),nullB=world(seed+77,'nullB').slice(108),w2=fit(train,false),w3=fit(train,true),z=[0,0],zero3=[0,0,0];let shuffled=hold.map((r,i)=>({...r,b:hold[(i+37)%hold.length].b}));let reversed=hold.map(r=>({...r,a:r.b,b:r.a}));let phase=hold.map(r=>({...r,a:-r.a}));let detune=hold.map((r,i)=>({...r,b:r.b*Math.cos(i*.07)}));let projection=Array.from({length:27},(_,i)=>i%27);return {seed,metrics:{T1:{linear:mse(hold,w2),quadratic:mse(hold,w3),zero:mse(hold,zero3)},T2:{linear:mse(shift,w2),quadratic:mse(shift,w3),zero:mse(shift,zero3)},T3:{quadratic:mse(nullA,w3),zero:mse(nullA,zero3)},T4:{quadratic:mse(nullB,w3),zero:mse(nullB,zero3)},T5:{coupled:mse(shuffled,w3),uncoupled:mse(shuffled,[w3[0],0,w3[2]])},T6:{coupled:mse(hold,w3),uncoupled:mse(hold,[w3[0],0,0])},T7:{ordered:mse(hold,w3),reversed:mse(reversed,w3)},T8:{normal:mse(hold,w3),inverted:mse(phase,w3)},T9:{normal:mse(hold,w3),detuned:mse(detune,w3)},T10:{slots:projection.length,unique:new Set(projection).size,mutationDetected:JSON.stringify({name:'Governor',identity:'resh'})!==JSON.stringify({name:'Impostor',identity:'resh'})}}};}
const output=SEEDS.map(run);if(typeof module!=='undefined')module.exports={run,output,SEEDS};if(typeof console!=='undefined')console.log(JSON.stringify(output));
